const sd = $getWorkflowStaticData('global'); sd.runs = sd.runs || {}; 
const u = $json;
const cb = u.callback_query, msg = u.message;
let o;
if (cb) o = { kind: 'callback', chatId: String(cb.message.chat.id), cbData: cb.data, cbId: cb.id };
else if (msg && msg.voice) o = { kind: 'voice', chatId: String(msg.chat.id), fileId: msg.voice.file_id };
else if (msg && msg.text) o = { kind: 'text', chatId: String(msg.chat.id), text: msg.text };
else o = { kind: 'ignore' };
const allowed = $env.ALLOWED_CHAT_ID;  // optional safety: only YOU can use the bot
if (allowed && o.chatId && o.chatId !== String(allowed)) o = { kind: 'ignore' };
return [{ json: o }];

const sd = $getWorkflowStaticData('global'); sd.runs = sd.runs || {}; sd.pending = sd.pending || {};
const j = $json, chatId = j.chatId;
const reply = (text) => ({ chat_id: chatId, text });
const out = { chatId, cbId: j.cbId || null, route: 'reply' };
if (j.kind === 'ignore') return [{ json: { route: 'ignore' } }];

if (j.kind === 'callback') {
  const [t, runId, arg] = String(j.cbData).split('|');
  const run = sd.runs[runId];
  if (!run) { out.tg = reply('⚠️ That session expired. Send me a new topic and I will start over.'); return [{ json: out }]; }
  out.runId = runId;
  if (t === 'a') { const a = run.angles[Number(arg)]; out.route = 'pick_angle'; out.angle = a.title + ' — ' + a.hook; }
  else if (t === 'c') { sd.pending[chatId] = { runId, awaiting: 'angle' }; out.tg = reply('✍️ Send your own angle now (text or voice note).'); }
  else if (t === 'h') { out.route = 'hook_ok'; out.hook = arg; }
  else if (t === 'r') { out.route = 'rewrite'; }
  else if (t === 'p' && arg === 'yt') { out.route = 'publish'; }
  else if (t === 'p') { out.tg = reply('👍 Saved! The video stays on your server in /data/clipforge/runs/' + runId + '/final.mp4'); }
  else if (t === 'x') { delete sd.runs[runId]; out.tg = reply('🗑️ Cancelled. Send a new topic any time.'); }
  else { out.tg = reply('🤔 Unknown button.'); }
  return [{ json: out }];
}

const text = String(j.text || '').trim();
const pend = sd.pending[chatId];
if (/^\/(start|help)/i.test(text)) {
  out.tg = reply('🎬 ClipForge AI\n\nSend me a topic (text or voice note) like:\n"Make a short about why the Mariana Trench has never been fully explored"\n\nI will research it, pitch angles, show a storyboard, and only render after you approve.');
} else if (pend && pend.awaiting === 'angle') {
  delete sd.pending[chatId];
  out.route = 'pick_angle'; out.runId = pend.runId; out.angle = text;
} else if (text.length < 4) {
  out.tg = reply('Send me a topic to make a Short about 🙂');
} else {
  out.route = 'new_topic'; out.topic = text;
}
return [{ json: out }];

const sd = $getWorkflowStaticData('global'); sd.runs = sd.runs || {}; sd.pending = sd.pending || {};
const TONE = $env.CREATOR_TONE || 'curious, confident, conversational, like a smart friend'; const LANG = $env.VIDEO_LANGUAGE || 'English'; const STYLE = $env.VISUAL_STYLE || 'cinematic, photorealistic, dramatic lighting, high detail';
const d = $('Decide').first().json;
const runId = Date.now().toString(36);
sd.runs[runId] = { chatId: d.chatId, topic: d.topic, created: new Date().toISOString() };
const ids = Object.keys(sd.runs).sort(); while (ids.length > 25) delete sd.runs[ids.shift()];   // keep memory small
const prompt = `You are an executive producer for a viral educational YouTube Shorts channel. Voice: ${TONE}. Language: ${LANG}.
The creator wants a 45-second Short about: "${d.topic}".
Return ONLY JSON: {"producer_notes": "2 sentences: who this is for + the single sharpest question you would ask the creator", "angles": [ {"title": "max 6 words", "hook": "the opening line, max 14 words", "why": "max 14 words on why it will hold attention"}, ... ]}
Exactly 3 angles: (1) a contrarian take that challenges what people believe, (2) an escalating story / countdown, (3) a mystery or curiosity-gap. Be specific to the topic, never generic.`;
return [{ json: { runId, chatId: d.chatId, tg: { chat_id: d.chatId, text: `🎬 Topic received: "${d.topic}"\n\n🧠 Your producer is brainstorming angles...` },
  gem: { contents: [{ role: 'user', parts: [{ text: prompt }] }], generationConfig: { responseMimeType: 'application/json', temperature: 0.9 } } } }];

const sd = $getWorkflowStaticData('global'); sd.runs = sd.runs || {}; sd.pending = sd.pending || {};
const getText = (r) => (r.candidates?.[0]?.content?.parts || []).map(p => p.text || '').join('');
const parseJson = (s) => JSON.parse(s.replace(/^```json\s*|^```\s*|```\s*$/gm, '').trim());
const p = $('Prep Topic').first().json; const run = sd.runs[p.runId];
const data = parseJson(getText($input.first().json));
const angles = (data.angles || []).slice(0, 3);
if (!angles.length) throw new Error('Gemini returned no angles');
run.angles = angles;
const lines = angles.map((a, i) => `${i + 1}️⃣ ${a.title}\n   🪝 ${a.hook}\n   💡 ${a.why}`);
const text = [`🎬 Topic: ${run.topic}`, '', `🧠 Producer notes: ${data.producer_notes}`, '', ...lines, '', '✅ GATE 1 of 3 — pick an angle, or write your own 👇'].join('\n');
return [{ json: { tg: { chat_id: p.chatId, text, reply_markup: { inline_keyboard: [
  angles.map((a, i) => ({ text: `${i + 1}️⃣`, callback_data: `a|${p.runId}|${i}` })),
  [{ text: '✍️ Custom angle', callback_data: `c|${p.runId}` }],
  [{ text: '❌ Cancel', callback_data: `x|${p.runId}` }] ] } } } }];

const sd = $getWorkflowStaticData('global'); sd.runs = sd.runs || {}; sd.pending = sd.pending || {};
const d = $('Decide').first().json; const run = sd.runs[d.runId]; run.angle = d.angle;
const prompt = `Research this for a 45-second expert-level YouTube Short.
TOPIC: ${run.topic}
ANGLE: ${d.angle}
Use live web search. Return 12-15 bullet facts. Each bullet must contain a specific number, date, name or quote AND the source name (journal, .gov/.edu, or reputable outlet). Include 2 counter-intuitive facts and 1 common misconception people believe. Plain text, no intro, no fluff. If you cannot verify something, leave it out.`;
return [{ json: { tg: { chat_id: d.chatId, text: `🔒 Angle locked:\n${d.angle}\n\n🔎 Researching with live web search... (about 1 minute)` },
  gem: { contents: [{ role: 'user', parts: [{ text: prompt }] }], tools: [{ google_search: {} }], generationConfig: { temperature: 0.3 } } } }];

const sd = $getWorkflowStaticData('global'); sd.runs = sd.runs || {}; sd.pending = sd.pending || {};
const getText = (r) => (r.candidates?.[0]?.content?.parts || []).map(p => p.text || '').join('');
const parseJson = (s) => JSON.parse(s.replace(/^```json\s*|^```\s*|```\s*$/gm, '').trim());
const d = $('Decide').first().json; const run = sd.runs[d.runId];
const r = $input.first().json; const text = getText(r);
if (!text) throw new Error('Research came back empty: ' + JSON.stringify(r).slice(0, 300));
const chunks = r.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
const seen = new Set(); const sources = [];
for (const c of chunks) { const w = c.web; if (w && !seen.has(w.title)) { seen.add(w.title); sources.push({ title: w.title, uri: w.uri }); } }
run.research = text; run.sources = sources;
return [{ json: { runId: d.runId, sources: sources.length } }];

const sd = $getWorkflowStaticData('global'); sd.runs = sd.runs || {}; sd.pending = sd.pending || {};
const d = $('Decide').first().json; 
return [{ json: { tg: { chat_id: d.chatId, text: '🔄 Rewriting the script with a fresh structure and new hooks...' } } }];

const sd = $getWorkflowStaticData('global'); sd.runs = sd.runs || {}; sd.pending = sd.pending || {};
const TONE = $env.CREATOR_TONE || 'curious, confident, conversational, like a smart friend'; const LANG = $env.VIDEO_LANGUAGE || 'English'; const STYLE = $env.VISUAL_STYLE || 'cinematic, photorealistic, dramatic lighting, high detail';
const d = $('Decide').first().json; const run = sd.runs[d.runId];
const redo = d.route === 'rewrite' ? '\nIMPORTANT: the creator REJECTED the previous draft. Use a completely different structure, different hooks and different scene order.' : '';
const prompt = `You are the head writer of a viral educational YouTube Shorts channel.
CREATOR VOICE: ${TONE}. LANGUAGE: ${LANG}. VISUAL STYLE for images: ${STYLE}.
TOPIC: ${run.topic}
CHOSEN ANGLE: ${run.angle}
VERIFIED RESEARCH NOTES (the ONLY source of facts. Never invent numbers, names or quotes):
${run.research}

Write a 40-50 second script (about 110-130 spoken words) with EXACTLY 10 scenes.
- Scene 1 = HOOK (max 14 words) that stops the scroll. Give two alternatives: hook_a (curiosity gap) and hook_b (contrarian / shocking). scenes[0].narration = hook_a.
- Scenes 2-4 escalate, one surprising fact each. Scenes 5-8 rapid delivery with concrete numbers. Scene 9 = payoff / twist.
- Scene 10 = LOOP ENDING: its last words must end mid-thought so they flow grammatically into the first words of the hook (like "...and that is exactly why"). Give close_a (flows into hook_a) and close_b (flows into hook_b). scenes[9].narration = close_a.
- Each narration: 8-14 words, short punchy sentences, conversational. Use "..." right before big reveals.
- Every claim must come from the research notes.
- visual_prompt: vertical 9:16 cinematic image description: concrete subject, camera angle, lighting. NO text or letters in the image. Vary the camera angle every scene.
- keyword: 1-3 word ALL-CAPS on-screen emphasis (or empty string).
- title: max 70 chars, no hashtags. description: 2 short lines. tags: 5-8.${redo}
Return ONLY JSON: {"title":"","description":"","tags":[],"hook_a":"","hook_b":"","close_a":"","close_b":"","scenes":[{"idx":1,"narration":"","visual_prompt":"","keyword":""}]}`;
return [{ json: { gem: { contents: [{ role: 'user', parts: [{ text: prompt }] }], generationConfig: { responseMimeType: 'application/json', temperature: 0.8 } } } }];

const sd = $getWorkflowStaticData('global'); sd.runs = sd.runs || {}; sd.pending = sd.pending || {};
const getText = (r) => (r.candidates?.[0]?.content?.parts || []).map(p => p.text || '').join('');
const parseJson = (s) => JSON.parse(s.replace(/^```json\s*|^```\s*|```\s*$/gm, '').trim());
const d = $('Decide').first().json; const run = sd.runs[d.runId];
const s = parseJson(getText($input.first().json));
if (!Array.isArray(s.scenes) || s.scenes.length < 6) throw new Error('Script has too few scenes');
s.scenes.forEach((sc, i) => { sc.idx = i + 1; sc.keyword = sc.keyword || ''; sc.visual_prompt = String(sc.visual_prompt || '').slice(0, 400); });
s.scenes[0].narration = s.hook_a; s.scenes[s.scenes.length - 1].narration = s.close_a;
run.script = s;
const prompt = `You are a ruthless fact-checker. Compare the SCRIPT against the RESEARCH NOTES.
Flag every factual claim in the script that is NOT directly supported by the notes (numbers, dates, names, causal claims).
RESEARCH NOTES:\n${run.research}\n\nSCRIPT:\n${s.scenes.map(x => x.idx + '. ' + x.narration).join('\n')}\n${s.hook_b}\n${s.close_b}
Return ONLY JSON: {"verdict":"pass" or "warn","issues":[{"scene":1,"claim":"","problem":""}]}`;
return [{ json: { gem: { contents: [{ role: 'user', parts: [{ text: prompt }] }], generationConfig: { responseMimeType: 'application/json', temperature: 0.1 } } } }];

const sd = $getWorkflowStaticData('global'); sd.runs = sd.runs || {}; sd.pending = sd.pending || {};
const getText = (r) => (r.candidates?.[0]?.content?.parts || []).map(p => p.text || '').join('');
const parseJson = (s) => JSON.parse(s.replace(/^```json\s*|^```\s*|```\s*$/gm, '').trim());
const d = $('Decide').first().json; const run = sd.runs[d.runId];
let fc; try { fc = parseJson(getText($input.first().json)); } catch (e) { fc = { verdict: 'warn', issues: [{ scene: 0, claim: 'fact-check parse failed', problem: 'review manually' }] }; }
run.factcheck = fc; return [{ json: { runId: d.runId } }];

const sd = $getWorkflowStaticData('global'); sd.runs = sd.runs || {}; sd.pending = sd.pending || {};
const TONE = $env.CREATOR_TONE || 'curious, confident, conversational, like a smart friend'; const LANG = $env.VIDEO_LANGUAGE || 'English'; const STYLE = $env.VISUAL_STYLE || 'cinematic, photorealistic, dramatic lighting, high detail';
const d = $('Decide').first().json; const run = sd.runs[d.runId];
return run.script.scenes.map((s, i) => ({ json: { runId: d.runId, idx: i + 1, seed: 1000 + i * 7,
  prompt: (s.visual_prompt + ', ' + STYLE + ', vertical 9:16, no text, no watermark').slice(0, 450) } }));

const sd = $getWorkflowStaticData('global'); sd.runs = sd.runs || {}; sd.pending = sd.pending || {};
const d = $('Decide').first().json; const run = sd.runs[d.runId]; const s = run.script; const fc = run.factcheck || {};
const issues = (fc.issues || []).slice(0, 4).map(i => `• scene ${i.scene}: ${i.problem}`).join('\n');
const src = (run.sources || []).slice(0, 4).map(x => x.title).join(', ');
let text = [`📝 ${s.title}`, '', `🅰️ Hook A: ${s.hook_a}`, `🅱️ Hook B: ${s.hook_b}`, '', ...s.scenes.slice(1, 9).map(x => `${x.idx}. ${x.narration}`), '',
  fc.verdict === 'pass' ? '✅ Fact-check: every claim matches the research.' : `⚠️ Fact-check flagged:\n${issues || 'review manually'}`,
  src ? `📚 Sources: ${src}` : '', '', '✅ GATE 2 of 3 — choose your hook (this also locks the script):'].filter(x => x !== null).join('\n');
if (text.length > 3900) text = text.slice(0, 3900) + '…';
return [{ json: { tg: { chat_id: d.chatId, text, reply_markup: { inline_keyboard: [
  [{ text: '🅰️ Use Hook A', callback_data: `h|${d.runId}|a` }, { text: '🅱️ Use Hook B', callback_data: `h|${d.runId}|b` }],
  [{ text: '🔄 Rewrite script', callback_data: `r|${d.runId}` }], [{ text: '❌ Cancel', callback_data: `x|${d.runId}` }] ] } } } }];

const sd = $getWorkflowStaticData('global'); sd.runs = sd.runs || {}; sd.pending = sd.pending || {};
const d = $('Decide').first().json; const run = sd.runs[d.runId]; const s = run.script;
const sc = JSON.parse(JSON.stringify(s.scenes)); const b = d.hook === 'b';
sc[0].narration = b ? s.hook_b : s.hook_a; sc[sc.length - 1].narration = b ? s.close_b : s.close_a;
run.final_scenes = sc; run.hook = d.hook; run.status = 'rendering';
const b64 = Buffer.from(JSON.stringify({ scenes: sc.map((x, i) => ({ idx: i + 1, narration: x.narration, keyword: x.keyword || '' })) })).toString('base64');
return [{ json: { runId: d.runId, b64, tg: { chat_id: d.chatId, text: `🎙️ Hook ${b ? 'B' : 'A'} locked.\nRecording the voiceover with ElevenLabs and editing your video... (about 2-4 minutes)` } } }];

const sd = $getWorkflowStaticData('global'); sd.runs = sd.runs || {}; sd.pending = sd.pending || {};
const d = $('Decide').first().json; const run = sd.runs[d.runId];
return run.final_scenes.map((s, i) => ({ json: { runId: d.runId, idx: i + 1, text: s.narration } }));

const sd = $getWorkflowStaticData('global'); sd.runs = sd.runs || {}; sd.pending = sd.pending || {};
const d = $('Decide').first().json; const run = sd.runs[d.runId]; const s = run.script;
const srcs = (run.sources || []).slice(0, 5).map(x => x.title).join(', ');
const desc = [s.description, srcs ? '\nSources: ' + srcs : '', '\n#Shorts'].join('\n');
return [{ json: { yt: { title: (s.title + ' #Shorts').slice(0, 100), description: desc, tags: (s.tags || []).join(',') },
  tg: { chat_id: d.chatId, text: '⬆️ Uploading to YouTube...' } } }];

const yt = $input.first().json; const url = 'https://www.youtube.com/shorts/' + yt.id;
const chatId = $('Decide').first().json.chatId; const title = $('Prep Publish').first().json.yt.title;
return [{ json: { url, title, tg: { chat_id: chatId, text: `✅ Uploaded as PRIVATE (change visibility in YouTube Studio):
${url}

Want another? Just send a new topic 🎬` } } }];

